  ["highground.modules.highground_already_includes_these_remove_only_these.b1a936"] = "Highground 已包含这些内容。只需删除以下单独下载的插件：\n{value2}。\n\n1. 关闭魔兽世界。\n2. 在插件管理器中卸载列出的独立下载，或只删除列出的文件夹。\n3. 重新安装 Highground，然后重启魔兽世界。\n\n请保留 Highground、所有 HighgroundModule 文件夹、HighgroundBountyData 和 HighgroundReputationData。两个数据插件都必须保持启用，否则 Highground 无法加载。",
