  ["shared.previewsamples.portraits_use_your_selected_player_or_your.6ec2ed"] = "肖像使用你选择的玩家或你的角色作为标签示例。这永远不会给他们带来好处。实时警报来自观察，包括目标、鼠标悬停和名牌。",
