  ["shared.previewsamples.click_the_wanted_card_or_view_bounty.b1ae32"] = "点击想要的卡片或查看奖励，以检查每个出资人，他们的条款，资金和到期。刷新 在样品奖励到达时显示禁用的按钮和加载程序。",
  ["shared.previewsamples.start_tracking_adds_a_target_to_my.e9b443"] = "开始跟踪 将目标添加到我的奖励中。检测到杀伤后，查看报告 将打开其状态。发布者将目标和奖励放在第一位，使用羊皮纸宽度的细节，并在需要时滚动。无法获得的肖像被标记。",
  ["shared.previewsamples.create_terms.1ea507"] = "创建条款",
  ["shared.previewsamples.build_a_sample_bounty.01af6d"] = "构建示例悬赏",
  ["shared.previewsamples.three_steps_target_reward_review_nothing_is.cc55e8"] = "三个步骤：目标、奖励、确认。最终确认前不会保存任何内容。默认条件为以任意方式击杀一次。",
  ["shared.previewsamples.save_returns_to_the_tour_sharing_is.631c62"] = "保存返回到旅行。共享是可选的。私人追踪可以使用零金币；共享奖励需要正值和过期。首选的完成需要发布者的审查。没有生存奖励被创建。",
  ["shared.previewsamples.use_gold_across_your_characters.423446"] = "将金币用于你的角色",
  ["shared.previewsamples.see_a_sample_wallet_and_the_bag.2652f4"] = "查看示例钱包和袋子金币工具提示。尝试两个开关，然后在\"创建 & 条款\"中输入大于可用金额的奖励。",
  ["shared.previewsamples.account_tracking_is_on_by_default_requiring.faa230"] = "账号追踪默认开启。“要求足够金币”默认关闭：超出预算的奖励会发出警告，但仍可创建。余额仅限此服务器或 Forever 服务器组。小号余额在你登录时更新；付款和转账仍需手动进行。",
  ["shared.previewsamples.guild_approval.d5172b"] = "行会批准",
  ["shared.previewsamples.submit_and_approve_a_guild_bounty.93c32d"] = "提交并批准公会悬赏",
  ["shared.previewsamples.try_awaiting_approval_officer_approval_and_rejection.1aed32"] = "尝试等待批准，官员批准和拒绝，然后检查由此产生的通缉卡. 即使没有公会，这些角色也可以在游览中使用。",
  ["shared.previewsamples.approved_guild_rewards_can_show_a_new.36cbe4"] = "经批准的公会奖励可以显示新奖励发布者。这是宣布奖励，而不是观察。与公会和全球悬赏榜共享奖励不会产生第二次付款义务。在 Forever 上，社区奖励仅与你规则集的成员同步。",
  ["shared.previewsamples.shared_arrivals.7e4e7c"] = "共同抵达",
  ["shared.previewsamples.a_bounty_matches_your_filters.542556"] = "悬赏符合你的筛选条件",
  ["shared.previewsamples.use_start_tracking_or_ignore_on_the.ac8ad1"] = "在传入的发布者上使用开始跟踪 或忽略。尝试示例警报设置和供资状态。这一目标尚未被发现。",
  ["shared.previewsamples.the_notification_minimum_counts_rewards_with_current.7ea6f7"] = "通知最低数量计算奖励与当前可用资金报告。导入的、过时的或没有资金的报价仍然可以区分。追踪不会带来金钱；忽略会让目标的悬赏和目击警报沉默。",
  ["shared.previewsamples.grow_a_bounty_s_pot.fc063b"] = "生长一个悬赏的锅",
  ["shared.previewsamples.add_a_sample_contribution_review_the_original.3e1e7c"] = "添加示例贡献，查看原始帖子的条件，并查看合并奖励更新。",
  ["shared.previewsamples.accepting_the_terms_means_the_original_poster.cb648e"] = "接受条款意味着原发布者决定领取申请是否符合资格。出资人应向同一被接受的赏金猎人支付其金额。金币不会由插件持有或转移。",
  ["shared.previewsamples.share_import.d10b63"] = "分享&导入",
  ["shared.previewsamples.copy_a_bounty_link_and_review_an.e6954f"] = "复制悬赏链接并审查导入",
  ["shared.previewsamples.sharing_outside_the_addon_is_optional_copy.b960a6"] = "在插件之外共享是可选的。复制全局、公会或私人悬赏链接，然后查看示例导入。",
  ["shared.previewsamples.choose_select_link_to_copy_press_ctrl.75c0bf"] = "选择“选择要复制的链接”，按 Ctrl+C 并发送悬赏链接。接收者选择“导入悬赏”。“在聊天中分享”适用于私人和团体悬赏。Discord 频道会单独打开共享悬赏榜的目标。指南链接在指南之外故意无效。",
  ["shared.previewsamples.kills_reports.48e18a"] = "杀戮与报告",
  ["shared.previewsamples.detected_kills_create_reports_automatically.0ec7e1"] = "自动创建报告",
  ["shared.previewsamples.use_view_sample_report_to_follow_review.4dce46"] = "使用查看示例报告 跟踪审查。尝试重复杀戮和截图成功，失败或重试。复印证明是可选的。",
  ["shared.previewsamples.readable_killing_blows_are_confirmed_locally_named.83de2e"] = "当地确认了可读的致命击打。指定荣誉积分可能包括助攻。屏幕截图复选框确认仅保存了图像。奖励批准和支付仍然是分开的；手动报告是为了错过的检测。这次旅行不需要屏幕截图。",
  ["shared.previewsamples.follow_reports_through_review_and_payment.7bf30e"] = "通过审核和付款跟踪报告",
  ["shared.previewsamples.browse_hunter_and_poster_examples_awaiting_review.ee1784"] = "浏览赏金猎人和发布者示例：等待审核，批准，付款和拒绝。试试批准、拒绝和标记已付款作为示例发布者。",
  ["shared.previewsamples.hunters_cannot_approve_their_own_reports_the.8e822e"] = "赏金猎人不能批准自己的报告。发布者审查证据，并通过游戏手动支付，然后记录该付款。重复杀戮可以计入多次杀戮目标，而无需为同一奖励支付两次费用。",
  ["shared.previewsamples.review_enemies_suggested_by_death_reports.470074"] = "审查死亡报告建议的敌人",
  ["shared.previewsamples.inspect_sample_reports_review_a_prefilled_bounty.a7057d"] = "检查示例报告，查看预填报酬，驳回建议或忽略敌人。",
  ["shared.previewsamples.suggestions_combine_your_deaths_and_participating_guild.4596f6"] = "建议将你的死亡和参与公会报告合并到配置窗口中。它们是要审查的线索，而不是服务器验证的杀死证明。在你选择可见范围并保存之前，不会发布任何内容。",
